import 'package:flutter/material.dart';
import '../../../core/widgets/common_widgets.dart';
import '../../../data/repositories/photobook_repository.dart';
class TrackingScreen extends StatefulWidget {final String orderNumber; const TrackingScreen({super.key,required this.orderNumber}); @override State<TrackingScreen> createState()=>_TrackingScreenState();}
class _TrackingScreenState extends State<TrackingScreen>{final _repo=PhotobookRepository(); late Future<dynamic> _f; @override void initState(){super.initState(); _f=_repo.getTracking(widget.orderNumber);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tracking')),body:FutureBuilder(future:_f,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const LoadingState(); if(s.hasError)return ErrorState(message:s.error.toString(),onRetry:()=>setState(()=>_f=_repo.getTracking(widget.orderNumber))); final items=s.data.items; if(items.isEmpty)return const EmptyState(title:'Tracking kosong',subtitle:'Belum ada data tracking.'); return ListView.builder(itemCount:items.length,itemBuilder:(_,i){final it=items[i]; return ListTile(title:Text(it.status),subtitle:Text('${it.description}\n${it.location} • ${it.date}'));});}));}
